const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));
let note='';
document.querySelector('#trip-form').addEventListener('submit',e=>{e.preventDefault();const date=new Date(document.querySelector('#when').value);if(date<new Date()){document.querySelector('#when').setCustomValidity('Lütfen gelecek bir tarih ve saat seçin.');document.querySelector('#when').reportValidity();return}note=`Taksi yolculuk talebi\nHareket: ${document.querySelector('#from').value.trim()}\nVarış: ${document.querySelector('#to').value.trim()}\nTarih: ${date.toLocaleString('tr-TR')}\nYolcu: ${document.querySelector('#passengers').value}\nAraç ve saat uygunluğunu öğrenmek istiyorum.`;document.querySelector('#trip-text').textContent=note;document.querySelector('#trip-result').hidden=false});
document.querySelector('#when').addEventListener('input',e=>e.target.setCustomValidity(''));
document.querySelector('#copy').addEventListener('click',async e=>{try{await navigator.clipboard.writeText(note);e.target.textContent='Kopyalandı ✓'}catch{e.target.textContent='Metni seçip kopyalayabilirsiniz';const range=document.createRange();range.selectNodeContents(document.querySelector('#trip-text'));window.getSelection().removeAllRanges();window.getSelection().addRange(range)}});
